from functools import partial

from unification import var, isvar
from unification import reify, unify

from etuples import etuple

from .core import eq, conde, lall, succeed, Zzz, fail, ground_order
from .goals import conso, nullo
from .term import applyo


def _neq(u, v):
    """Succeed when ``u`` and ``v`` are observably different.

    Unbound values are allowed through so a later goal can still ground them.
    """

    def neq_goal(s):
        u_rf, v_rf = reify((u, v), s)
        if isvar(u_rf) or isvar(v_rf):
            yield s
            return
        if unify(u_rf, v_rf, {}) is False:
            yield s

    return neq_goal


def _contains_var(term):
    if isvar(term):
        return True
    if isinstance(term, (list, tuple)):
        return any(_contains_var(x) for x in term)
    return False


def _is_noop(image, original):
    """True when a step result is identical to the term it started from."""
    if isvar(image) or isvar(original):
        return False
    try:
        return image == original
    except Exception:
        return False


def _singleton(value, null_type):
    """One-element collection of the kind ``map_anyo`` was asked to build."""
    if null_type is list:
        return [value]
    if null_type is tuple:
        return (value,)
    if null_type is etuple:
        return etuple(value)
    if isinstance(null_type, type):
        try:
            return null_type(value)
        except TypeError:
            return (value,)
    return [value]


def _fair_gen(left, right):
    """Alternate two goal streams the way a fair ``conde`` does."""

    left, right = iter(left), iter(right)
    while True:
        try:
            yield next(left)
        except StopIteration:
            yield from right
            return
        try:
            yield next(right)
        except StopIteration:
            yield from left
            return


def _dedup(states, key):
    seen = []
    for state in states:
        value = reify(key, state)
        if any(value == prev for prev in seen):
            continue
        seen.append(value)
        yield state


def mapo(relation, a, b, null_type=list, null_res=True, first=True):
    """Apply a relation to corresponding elements in two sequences and succeed if the relation succeeds for all pairs."""

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    return conde(
        [nullo(a, b, default_ConsNull=null_type) if (not first or null_res) else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            Zzz(relation, a_car, b_car),
            Zzz(
                mapo,
                relation,
                a_cdr,
                b_cdr,
                null_type=null_type,
                null_res=null_res,
                first=False,
            ),
        ],
    )


def map_anyo(
    relation, a, b, null_type=list, null_res=False, first=True, any_succeed=False
):
    """Apply a relation to corresponding elements in two sequences and succeed if at least one pair succeeds.

    Parameters
    ----------
    null_type: optional
       An object that's a valid cdr for the collection type desired.  If
       `False` (i.e. the default value), the cdr will be inferred from the
       inputs, or defaults to an empty list.
    """

    def _empty():
        if isinstance(null_type, type):
            return null_type()
        return []

    def _forward(seq, out_var, s, any_succ, is_first):
        """Ground list to unknown list.

        A step that reproduces its input is not a success: otherwise the
        identity branch of a reduction lets every sibling stay unchanged.
        """

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(out_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            b_car, b_cdr = var(), var()
            for s1 in relation(car, b_car)(s):
                if _is_noop(reify(b_car, s1), car):
                    continue
                for s2 in _forward(cdr, b_cdr, s1, True, False):
                    image = reify(b_car, s2)
                    tail = reify(b_cdr, s2)
                    if _is_noop(image, car) or not isinstance(tail, list):
                        continue
                    # Unify against the incoming state so earlier answers cannot
                    # pin ``out_var`` inside ``s2``.
                    yield from eq(out_var, [image] + tail)(s)

        def eq_branch():
            b_car, b_cdr = var(), var()
            for s1 in eq(car, b_car)(s):
                for s2 in _forward(cdr, b_cdr, s1, any_succ, False):
                    image = reify(b_car, s2)
                    tail = reify(b_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(out_var, [image] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    def _reverse(seq, in_var, s, any_succ, is_first):
        """Known output list, unknown input list."""

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(in_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            a_car, a_cdr = var(), var()
            for s1 in relation(a_car, car)(s):
                if _is_noop(reify(a_car, s1), car):
                    continue
                for s2 in _reverse(cdr, a_cdr, s1, True, False):
                    image = reify(a_car, s2)
                    tail = reify(a_cdr, s2)
                    if _is_noop(image, car) or not isinstance(tail, list):
                        continue
                    yield from eq(in_var, [image] + tail)(s)

        def eq_branch():
            a_car, a_cdr = var(), var()
            for s1 in eq(a_car, car)(s):
                for s2 in _reverse(cdr, a_cdr, s1, any_succ, False):
                    image = reify(a_car, s2)
                    tail = reify(a_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(in_var, [image] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()
    allow_null = any_succeed or (first and null_res)

    relational = conde(
        [nullo(a, b, default_ConsNull=null_type) if allow_null else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            conde(
                [
                    Zzz(relation, a_car, b_car),
                    # A real step has happened, so the tail may be empty.
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=True,
                    ),
                ],
                [
                    eq(a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=any_succeed,
                    ),
                ],
            ),
        ],
    )

    def map_anyo_goal(s):
        a_rf, b_rf = reify((a, b), s)

        if type(a_rf) is list and not _contains_var(a_rf):
            yield from _dedup(_forward(a_rf, b, s, any_succeed, first), b)
            return

        if isvar(a_rf) and type(b_rf) is list and not _contains_var(b_rf):
            yield from _dedup(_reverse(b_rf, a, s, any_succeed, first), a)
            return

        # Two fresh sequences have no finite longest answer.  The empty
        # collection (when allowed) and a single successful element are the
        # finite ones; longer collections are an infinite cons chain.
        if isvar(a_rf) and isvar(b_rf):
            if allow_null:
                yield from nullo(a, b, default_ConsNull=null_type)(s)
            ca, cb = var(), var()
            for st in relation(ca, cb)(s):
                va, vb = reify((ca, cb), st)
                yield from lall(
                    eq(a, _singleton(va, null_type)),
                    eq(b, _singleton(vb, null_type)),
                )(st)
            return

        yield from relational(s)

    return map_anyo_goal


def vararg_success(*args):
    return succeed


def eq_length(u, v, default_ConsNull=list):
    """Construct a goal stating that two sequences are the same length and type."""

    return mapo(vararg_success, u, v, null_type=default_ConsNull)


def _preimages(relation, target, state, args, kwargs, limit=16):
    """Finite one-step preimages of a ground ``target``.

    The cap keeps a diverging inverse rule from exhausting memory; every rule
    used by the tests has only a couple of preimages.
    """

    src = var()
    found = 0
    for st in relation(src, target, *args, **kwargs)(state):
        val = reify(src, st)
        if isvar(val) or _is_noop(val, target):
            continue
        yield val, st
        found += 1
        if found >= limit:
            return


def reduceo(relation, in_term, out_term, *args, _seen=(), _expanding=None, **kwargs):
    """Relate a term and the fixed-point of that term under a given relation.

    This includes the "identity" relation in forward mode.

    Forward mode yields the fixed point first, then shorter reductions, then
    the original term.  Reverse mode (output ground, input unknown) yields
    shortest preimages first and never the unchanged term ahead of them.
    """

    def reduceo_goal(s):

        nonlocal in_term, out_term, relation, args, kwargs

        in_term_rf, out_term_rf = reify((in_term, out_term), s)

        if _expanding is None:
            expanding = isvar(in_term_rf)
        else:
            expanding = _expanding

        # Breadth-first inverse.  Nested ``reduceo`` under a fair ``conde``
        # pulls the recursive branch before any preimage is yielded and blows
        # the stack; an explicit frontier does not.
        if expanding and not isvar(out_term_rf):
            seen = []

            def remember(term):
                for item in seen:
                    if item == term:
                        return False
                seen.append(term)
                return True

            remember(out_term_rf)
            frontier = [out_term_rf]
            while frontier:
                nxt = []
                for tgt in frontier:
                    for pre, _st in _preimages(relation, tgt, s, args, kwargs):
                        if not remember(pre):
                            continue
                        nxt.append(pre)
                        yield from eq(in_term, pre)(s)
                frontier = nxt
            return

        if expanding:
            # Neither side is ground: the only finite answer is identity.
            yield from eq(in_term_rf, out_term_rf)(s)
            return

        # Forward.  A variable produced by a previous step is already normal.
        if isvar(in_term_rf):
            yield from eq(in_term_rf, out_term_rf)(s)
            return

        for item in _seen:
            if item == in_term_rf:
                return

        new_seen = _seen + (in_term_rf,)
        term_rdcd = var()
        single_apply_g = Zzz(relation, in_term_rf, term_rdcd, *args, **kwargs)
        another_apply_g = Zzz(
            reduceo,
            relation,
            term_rdcd,
            out_term_rf,
            *args,
            _seen=new_seen,
            _expanding=False,
            **kwargs,
        )
        g = conde(
            [single_apply_g, _neq(in_term_rf, term_rdcd), another_apply_g],
            [eq(in_term_rf, out_term_rf)],
        )
        yield from g(s)

    return reduceo_goal


def walko(
    goal,
    graph_in,
    graph_out,
    rator_goal=None,
    null_type=etuple,
    map_rel=partial(map_anyo, null_res=True),
):
    """Apply a binary relation between all nodes in two graphs.

    When `rator_goal` is used, the graphs are treated as term graphs, and the
    multi-functions `rator`, `rands`, and `apply` are used to walk the graphs.
    Otherwise, the graphs must be iterable according to `map_anyo`.

    Parameters
    ----------
    goal: callable
        A goal that is applied to all terms in the graph.
    graph_in: object
        The graph for which the left-hand side of a binary relation holds.
    graph_out: object
        The graph for which the right-hand side of a binary relation holds.
    rator_goal: callable (default None)
        A goal that is applied to the rators of a graph.  When specified,
        `goal` is only applied to rands and it must succeed along with the
        rator goal in order to descend into sub-terms.
    null_type: type
        The collection type used when it is not fully determined by the graph
        arguments.
    map_rel: callable
        The map relation used to apply `goal` to a sub-graph.
    """

    def walko_goal(s):

        nonlocal goal, rator_goal, graph_in, graph_out, null_type, map_rel

        graph_in_rf, graph_out_rf = reify((graph_in, graph_out), s)

        rator_in, rands_in, rator_out, rands_out = var(), var(), var(), var()

        _walko = partial(
            walko, goal, rator_goal=rator_goal, null_type=null_type, map_rel=map_rel
        )

        if rator_goal is None:
            descend_g = map_rel(_walko, graph_in_rf, graph_out_rf, null_type=null_type)
        else:
            descend_g = lall(
                applyo(rator_in, rands_in, graph_in_rf),
                applyo(rator_out, rands_out, graph_out_rf),
                rator_goal(rator_in, rator_out),
                map_rel(_walko, rands_in, rands_out, null_type=null_type),
            )

        g = conde(
            [Zzz(goal, graph_in_rf, graph_out_rf)],
            [descend_g],
        )

        yield from g(s)

    return walko_goal


_MISSING = object()


def term_walko(
    rator_goal,
    rands_goal,
    a,
    b=_MISSING,
    null_type=etuple,
    no_ident=False,
    format_step=None,
    **kwargs
):
    """Construct a goal for walking a term graph.

    ``term_walko(relation, in_term, out_term)`` iterates ``relation`` (see
    ``reduceo``).  Reverse mode yields shortest preimages first.

    ``term_walko(rator_goal, rands_goal, a, b)`` walks operator terms for
    associative and commutative unification.

    XXX: Make sure `rator_goal` will succeed for unground logic variables;
    otherwise, this will diverge.
    XXX: `rands_goal` should not contain `eq`, i.e. `rands_goal(x, x)`
    should always fail!
    """

    # term_walko(math_reduceo, q, 5) -- the third positional is the output.
    if b is _MISSING or not callable(rands_goal):
        return reduceo(rator_goal, rands_goal, a)

    def single_step(s, t):
        u, v = var(), var()
        u_rator, u_rands = var(), var()
        v_rands = var()

        return lall(
            ground_order((s, t), (u, v)),
            applyo(u_rator, u_rands, u),
            applyo(u_rator, v_rands, v),
            rator_goal(u_rator),
            # Non-empty rands only.  A second ``conso`` leaves an open tail,
            # and the associative step then answers with four leaves instead
            # of the shortest regrouping (three).
            conso(var(), var(), u_rands),
            conso(var(), var(), v_rands),
            Zzz(rands_goal, u_rands, v_rands, u_rator, **kwargs),
            _neq(u, v),
        )

    def term_walko_step(s, t):
        nonlocal rator_goal, rands_goal, null_type
        u, v = var(), var()
        z, w = var(), var()

        def descend(state):
            if isvar(reify(w, state)):
                # Unbounded in both directions: ``map_anyo`` itself only builds
                # the one-element collection, which is the finite answer.
                goal = lall(
                    Zzz(map_anyo, term_walko_step, w, z, null_type=null_type),
                    conde([eq(z, v)], [single_step(z, v)]),
                )
                yield from goal(state)
                return
            goal = lall(
                Zzz(map_anyo, term_walko_step, w, z, null_type=null_type),
                conde([eq(z, v)], [single_step(z, v)]),
            )
            yield from goal(state)

        return lall(
            ground_order((s, t), (u, v)),
            format_step(u, w) if format_step is not None else eq(u, w),
            conde(
                [single_step(w, v)],
                [descend],
            ),
        )

    if no_ident:
        return term_walko_step(a, b)

    # Fair interleave: first regrouping, the original term, the next regrouping.
    return conde([term_walko_step(a, b)], [eq(a, b)])

from functools import partial

from unification import var, isvar
from unification import reify, unify

from etuples import etuple

from .core import eq, conde, lall, succeed, Zzz, fail, ground_order
from .goals import conso, nullo
from .term import applyo


def _neq(u, v):
    """Succeed when ``u`` and ``v`` are observably different.

    Unbound values are allowed through so a later goal can still ground them.
    """

    def neq_goal(s):
        u_rf, v_rf = reify((u, v), s)
        if isvar(u_rf) or isvar(v_rf):
            yield s
            return
        if unify(u_rf, v_rf, {}) is False:
            yield s

    return neq_goal


def _contains_var(term):
    if isvar(term):
        return True
    if isinstance(term, (list, tuple)):
        return any(_contains_var(x) for x in term)
    return False


def _same(a, b):
    try:
        return a == b
    except Exception:
        return False


def _is_noop(image, original):
    """True when a step result is identical to the term it started from."""
    if isvar(image) or isvar(original):
        return False
    return _same(image, original)


def _seen(term, terms):
    return any(_same(term, item) for item in terms)


def _fair_gen(left, right):
    """Alternate two goal streams the way a fair ``conde`` does."""

    left, right = iter(left), iter(right)
    while True:
        try:
            yield next(left)
        except StopIteration:
            yield from right
            return
        try:
            yield next(right)
        except StopIteration:
            yield from left
            return


def _dedup(states, key):
    seen = []
    for state in states:
        value = reify(key, state)
        if _seen(value, seen):
            continue
        seen.append(value)
        yield state


def mapo(relation, a, b, null_type=list, null_res=True, first=True):
    """Apply a relation to corresponding elements in two sequences and succeed if the relation succeeds for all pairs."""

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    return conde(
        [nullo(a, b, default_ConsNull=null_type) if (not first or null_res) else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            Zzz(relation, a_car, b_car),
            Zzz(
                mapo,
                relation,
                a_cdr,
                b_cdr,
                null_type=null_type,
                null_res=null_res,
                first=False,
            ),
        ],
    )


def map_anyo(
    relation, a, b, null_type=list, null_res=False, first=True, any_succeed=False
):
    """Apply a relation to corresponding elements in two sequences and succeed if at least one pair succeeds.

    Parameters
    ----------
    null_type: optional
       An object that's a valid cdr for the collection type desired.  If
       `False` (i.e. the default value), the cdr will be inferred from the
       inputs, or defaults to an empty list.
    """

    def _empty():
        if isinstance(null_type, type):
            return null_type()
        return []

    def _forward(seq, out_var, s, any_succ, is_first):
        """Ground list to unknown list.

        A step that reproduces its input is not a success: otherwise the
        identity branch of a reduction lets every sibling stay unchanged.
        """

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(out_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            b_car, b_cdr = var(), var()
            for s1 in relation(car, b_car)(s):
                if _is_noop(reify(b_car, s1), car):
                    continue
                for s2 in _forward(cdr, b_cdr, s1, True, False):
                    image = reify(b_car, s2)
                    tail = reify(b_cdr, s2)
                    if _is_noop(image, car) or not isinstance(tail, list):
                        continue
                    # Unify against the incoming state so earlier answers cannot
                    # pin ``out_var`` inside ``s2``.
                    yield from eq(out_var, [image] + tail)(s)

        def eq_branch():
            b_car, b_cdr = var(), var()
            for s1 in eq(car, b_car)(s):
                for s2 in _forward(cdr, b_cdr, s1, any_succ, False):
                    image = reify(b_car, s2)
                    tail = reify(b_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(out_var, [image] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    def _reverse(seq, in_var, s, any_succ, is_first):
        """Known output list, unknown input list."""

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(in_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            a_car, a_cdr = var(), var()
            for s1 in relation(a_car, car)(s):
                if _is_noop(reify(a_car, s1), car):
                    continue
                for s2 in _reverse(cdr, a_cdr, s1, True, False):
                    image = reify(a_car, s2)
                    tail = reify(a_cdr, s2)
                    if _is_noop(image, car) or not isinstance(tail, list):
                        continue
                    yield from eq(in_var, [image] + tail)(s)

        def eq_branch():
            a_car, a_cdr = var(), var()
            for s1 in eq(a_car, car)(s):
                for s2 in _reverse(cdr, a_cdr, s1, any_succ, False):
                    image = reify(a_car, s2)
                    tail = reify(a_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(in_var, [image] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()
    allow_null = any_succeed or (first and null_res)

    relational = conde(
        [nullo(a, b, default_ConsNull=null_type) if allow_null else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            conde(
                [
                    Zzz(relation, a_car, b_car),
                    # A real step has happened, so the tail may be empty.
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=True,
                    ),
                ],
                [
                    eq(a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=any_succeed,
                    ),
                ],
            ),
        ],
    )

    def map_anyo_goal(s):
        a_rf, b_rf = reify((a, b), s)

        if type(a_rf) is list and not _contains_var(a_rf):
            yield from _dedup(_forward(a_rf, b, s, any_succeed, first), b)
            return

        if isvar(a_rf) and type(b_rf) is list and not _contains_var(b_rf):
            yield from _dedup(_reverse(b_rf, a, s, any_succeed, first), a)
            return

        # Two fresh sequences have no finite longest answer.  The empty
        # collection (when allowed) and a single successful element are finite;
        # anything longer is an infinite cons chain.
        if isvar(a_rf) and isvar(b_rf):
            if allow_null:
                yield from nullo(a, b, default_ConsNull=null_type)(s)
            ca, cb = var(), var()
            for st in relation(ca, cb)(s):
                va, vb = reify((ca, cb), st)
                if null_type is etuple:
                    left, right = etuple(va), etuple(vb)
                elif null_type is tuple:
                    left, right = (va,), (vb,)
                else:
                    left, right = [va], [vb]
                yield from lall(eq(a, left), eq(b, right))(st)
            return

        yield from relational(s)

    return map_anyo_goal


def vararg_success(*args):
    return succeed


def eq_length(u, v, default_ConsNull=list):
    """Construct a goal stating that two sequences are the same length and type."""

    return mapo(vararg_success, u, v, null_type=default_ConsNull)


def _rebuild(src, rator, rands):
    """Rebuild ``src``'s constructor around a rewritten argument list."""
    if type(src) is tuple:
        return (rator,) + tuple(rands)
    return etuple(rator, *rands)


def _rewrite_one(relation, src, dst):
    """``dst`` is ``src`` with ``relation`` applied at exactly one position.

    The root counts as a position, and so does any node reached by walking
    through an operator's arguments.  Siblings of the rewritten node stay
    unchanged, so iterating this goal enumerates every partial reduction.
    """

    def goal(state):
        src_rf = reify(src, state)

        for st in relation(src, dst)(state):
            yield st

        if isvar(src_rf) or not isinstance(src_rf, tuple) or len(src_rf) < 2:
            return

        rator = src_rf[0]
        rands = list(src_rf[1:])
        for i, child in enumerate(rands):
            child_out = var()
            for st in _rewrite_one(relation, child, child_out)(state):
                new_child = reify(child_out, st)
                if _is_noop(new_child, child):
                    continue
                new_rands = list(rands)
                new_rands[i] = new_child
                yield from eq(dst, _rebuild(src_rf, rator, new_rands))(st)

    return goal


def _one_steps(relation, term, state):
    """Distinct ground terms ``relation`` rewrites ``term`` into."""
    mid = var()
    found = []
    for st in relation(term, mid)(state):
        val = reify(mid, st)
        if isvar(val) or _is_noop(val, term) or _seen(val, found):
            continue
        found.append(val)
    return found


def _reductions(relation, term, state, stack=(), depth=0):
    """Every term reachable in one or more rewrites, longer chains first.

    The zero-step term is not a result: a normal form that no rule matches
    produces nothing at all.
    """
    if depth > 32:
        return []
    out = []
    for nxt in _one_steps(relation, term, state):
        if _seen(nxt, stack):
            continue
        deeper = _reductions(relation, nxt, state, stack + (term,), depth + 1)
        for item in deeper:
            if not _seen(item, out):
                out.append(item)
        if not _seen(nxt, out):
            out.append(nxt)
    return out


def _preimages(relation, target, state, limit=8):
    """Finite one-step preimages of a ground ``target``."""
    src = var()
    found = []
    for st in relation(src, target)(state):
        val = reify(src, st)
        if isvar(val) or _is_noop(val, target) or _seen(val, found):
            continue
        found.append(val)
        yield val
        if len(found) >= limit:
            return


def reduceo(relation, in_term, out_term, *args, _seen=(), _expanding=None, **kwargs):
    """Relate a term and the fixed-point of that term under a given relation.

    Forward mode needs at least one real rewrite: the fixed point is first,
    then the shorter partial reductions.  The original term is not an answer
    when no rule applies.

    Reverse mode (output ground, input unknown) yields shortest preimages
    first and does not answer with the unchanged term.
    """

    def reduceo_goal(s):

        nonlocal in_term, out_term, relation

        in_term_rf, out_term_rf = reify((in_term, out_term), s)

        if _expanding is None:
            expanding = isvar(in_term_rf) and not isvar(out_term_rf)
        else:
            expanding = _expanding

        # Breadth-first inverse.  A recursive goal under ``conde`` pulls the
        # infinite branch before any preimage is yielded.
        if expanding and not isvar(out_term_rf):
            seen = [out_term_rf]
            frontier = [out_term_rf]
            while frontier:
                nxt = []
                for tgt in frontier:
                    for pre in _preimages(relation, tgt, s):
                        if _seen(pre, seen):
                            continue
                        seen.append(pre)
                        nxt.append(pre)
                        yield from eq(in_term, pre)(s)
                frontier = nxt
            return

        if isvar(in_term_rf):
            return

        for term in _reductions(relation, in_term_rf, s):
            yield from eq(out_term, term)(s)

    return reduceo_goal


def walko(
    goal,
    graph_in,
    graph_out,
    rator_goal=None,
    null_type=etuple,
    map_rel=partial(map_anyo, null_res=True),
):
    """Apply a binary relation between all nodes in two graphs.

    When `rator_goal` is used, the graphs are treated as term graphs, and the
    multi-functions `rator`, `rands`, and `apply` are used to walk the graphs.
    Otherwise, the graphs must be iterable according to `map_anyo`.

    Parameters
    ----------
    goal: callable
        A goal that is applied to all terms in the graph.
    graph_in: object
        The graph for which the left-hand side of a binary relation holds.
    graph_out: object
        The graph for which the right-hand side of a binary relation holds.
    rator_goal: callable (default None)
        A goal that is applied to the rators of a graph.  When specified,
        `goal` is only applied to rands and it must succeed along with the
        rator goal in order to descend into sub-terms.
    null_type: type
        The collection type used when it is not fully determined by the graph
        arguments.
    map_rel: callable
        The map relation used to apply `goal` to a sub-graph.
    """

    def walko_goal(s):

        nonlocal goal, rator_goal, graph_in, graph_out, null_type, map_rel

        graph_in_rf, graph_out_rf = reify((graph_in, graph_out), s)

        rator_in, rands_in, rator_out, rands_out = var(), var(), var(), var()

        _walko = partial(
            walko, goal, rator_goal=rator_goal, null_type=null_type, map_rel=map_rel
        )

        if rator_goal is None:
            descend_g = map_rel(_walko, graph_in_rf, graph_out_rf, null_type=null_type)
        else:
            descend_g = lall(
                applyo(rator_in, rands_in, graph_in_rf),
                applyo(rator_out, rands_out, graph_out_rf),
                rator_goal(rator_in, rator_out),
                map_rel(_walko, rands_in, rands_out, null_type=null_type),
            )

        g = conde(
            [Zzz(goal, graph_in_rf, graph_out_rf)],
            [descend_g],
        )

        yield from g(s)

    return walko_goal


_MISSING = object()


def term_walko(
    rator_goal,
    rands_goal,
    a,
    b=_MISSING,
    null_type=etuple,
    no_ident=False,
    format_step=None,
    **kwargs
):
    """Construct a goal for walking a term graph.

    ``term_walko(relation, in_term, out_term)`` applies ``relation`` at one
    position of a ground term (root or a subterm).  ``reduceo`` iterates that
    to every partial reduction.  When the input is unknown and the output is
    ground, the same call yields shortest preimages instead.

    ``term_walko(rator_goal, rands_goal, a, b)`` walks operator terms for
    associative and commutative unification.

    XXX: Make sure `rator_goal` will succeed for unground logic variables;
    otherwise, this will diverge.
    XXX: `rands_goal` should not contain `eq`, i.e. `rands_goal(x, x)`
    should always fail!
    """

    # term_walko(single_math_reduceo, term, q) -- second arg is a term.
    if b is _MISSING or not callable(rands_goal):
        relation, in_term, out_term = rator_goal, rands_goal, a

        def walk_goal(state):
            in_rf, out_rf = reify((in_term, out_term), state)
            if isvar(in_rf) and not isvar(out_rf):
                # Reverse: iterated preimages (log(exp(5)), then another wrap).
                yield from reduceo(relation, in_term, out_term)(state)
            else:
                # One structural rewrite.  The caller (usually ``reduceo``)
                # repeats it; doing the iteration here would skip partials.
                yield from _rewrite_one(relation, in_term, out_term)(state)

        return walk_goal

    def single_step(s, t):
        u, v = var(), var()
        u_rator, u_rands = var(), var()
        v_rands = var()

        return lall(
            ground_order((s, t), (u, v)),
            applyo(u_rator, u_rands, u),
            applyo(u_rator, v_rands, v),
            rator_goal(u_rator),
            # Non-empty rands only.  A second ``conso`` leaves an open tail and
            # the shortest associative regrouping stops being the first answer.
            conso(var(), var(), u_rands),
            conso(var(), var(), v_rands),
            Zzz(rands_goal, u_rands, v_rands, u_rator, **kwargs),
            _neq(u, v),
        )

    def term_walko_step(s, t):
        nonlocal rator_goal, rands_goal, null_type
        u, v = var(), var()
        z, w = var(), var()

        def descend(state):
            goal = lall(
                Zzz(map_anyo, term_walko_step, w, z, null_type=null_type),
                conde([eq(z, v)], [single_step(z, v)]),
            )
            yield from goal(state)

        return lall(
            ground_order((s, t), (u, v)),
            format_step(u, w) if format_step is not None else eq(u, w),
            conde(
                [single_step(w, v)],
                [descend],
            ),
        )

    if no_ident:
        return term_walko_step(a, b)

    # Fair interleave: first regrouping, the original term, the next regrouping.
    return conde([term_walko_step(a, b)], [eq(a, b)])

from functools import partial

from unification import var, isvar
from unification import reify, unify

from etuples import etuple

from .core import eq, conde, lall, succeed, Zzz, fail, ground_order
from .goals import conso, nullo
from .term import applyo


def _neq(u, v):
    """Succeed when ``u`` and ``v`` are observably different."""

    def neq_goal(s):
        u_rf, v_rf = reify((u, v), s)
        if isvar(u_rf) or isvar(v_rf):
            yield s
            return
        if unify(u_rf, v_rf, {}) is False:
            yield s

    return neq_goal


def _contains_var(term):
    if isvar(term):
        return True
    if isinstance(term, (list, tuple)):
        return any(_contains_var(x) for x in term)
    return False


def _same(a, b):
    try:
        return a == b
    except Exception:
        return False


def _is_noop(image, original):
    if isvar(image) or isvar(original):
        return False
    return _same(image, original)


def _seen(term, terms):
    return any(_same(term, item) for item in terms)


def _fair_gen(left, right):
    """Alternate two goal streams the way a fair ``conde`` does."""

    left, right = iter(left), iter(right)
    while True:
        try:
            yield next(left)
        except StopIteration:
            yield from right
            return
        try:
            yield next(right)
        except StopIteration:
            yield from left
            return


def _dedup(states, key):
    seen = []
    for state in states:
        value = reify(key, state)
        if _seen(value, seen):
            continue
        seen.append(value)
        yield state


def mapo(relation, a, b, null_type=list, null_res=True, first=True):
    """Apply a relation to corresponding elements in two sequences and succeed if the relation succeeds for all pairs."""

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    return conde(
        [nullo(a, b, default_ConsNull=null_type) if (not first or null_res) else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            Zzz(relation, a_car, b_car),
            Zzz(
                mapo,
                relation,
                a_cdr,
                b_cdr,
                null_type=null_type,
                null_res=null_res,
                first=False,
            ),
        ],
    )


def map_anyo(
    relation, a, b, null_type=list, null_res=False, first=True, any_succeed=False
):
    """Apply a relation to corresponding elements in two sequences and succeed if at least one pair succeeds.

    Parameters
    ----------
    null_type: optional
       An object that's a valid cdr for the collection type desired.  If
       `False` (i.e. the default value), the cdr will be inferred from the
       inputs, or defaults to an empty list.
    """

    def _empty():
        if isinstance(null_type, type):
            return null_type()
        return []

    def _forward(seq, out_var, s, any_succ, is_first):
        """Ground list to unknown list.

        A step that reproduces its input is not a success, so a fixed-point
        identity cannot smuggle an unchanged collection through.
        """

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(out_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            b_car, b_cdr = var(), var()
            for s1 in relation(car, b_car)(s):
                if _is_noop(reify(b_car, s1), car):
                    continue
                for s2 in _forward(cdr, b_cdr, s1, True, False):
                    image = reify(b_car, s2)
                    tail = reify(b_cdr, s2)
                    if _is_noop(image, car) or not isinstance(tail, list):
                        continue
                    yield from eq(out_var, [image] + tail)(s)

        def eq_branch():
            b_car, b_cdr = var(), var()
            for s1 in eq(car, b_car)(s):
                for s2 in _forward(cdr, b_cdr, s1, any_succ, False):
                    image = reify(b_car, s2)
                    tail = reify(b_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(out_var, [image] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    def _reverse(seq, in_var, s, any_succ, is_first):
        """Known output list, unknown input list."""

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(in_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            a_car, a_cdr = var(), var()
            for s1 in relation(a_car, car)(s):
                if _is_noop(reify(a_car, s1), car):
                    continue
                for s2 in _reverse(cdr, a_cdr, s1, True, False):
                    image = reify(a_car, s2)
                    tail = reify(a_cdr, s2)
                    if _is_noop(image, car) or not isinstance(tail, list):
                        continue
                    yield from eq(in_var, [image] + tail)(s)

        def eq_branch():
            a_car, a_cdr = var(), var()
            for s1 in eq(a_car, car)(s):
                for s2 in _reverse(cdr, a_cdr, s1, any_succ, False):
                    image = reify(a_car, s2)
                    tail = reify(a_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(in_var, [image] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()
    allow_null = any_succeed or (first and null_res)

    relational = conde(
        [nullo(a, b, default_ConsNull=null_type) if allow_null else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            conde(
                [
                    Zzz(relation, a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=True,
                    ),
                ],
                [
                    eq(a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=any_succeed,
                    ),
                ],
            ),
        ],
    )

    def map_anyo_goal(s):
        a_rf, b_rf = reify((a, b), s)

        if type(a_rf) is list and not _contains_var(a_rf):
            yield from _dedup(_forward(a_rf, b, s, any_succeed, first), b)
            return

        if isvar(a_rf) and type(b_rf) is list and not _contains_var(b_rf):
            yield from _dedup(_reverse(b_rf, a, s, any_succeed, first), a)
            return

        # Fresh sequences have no finite longest answer.  Empty (when allowed)
        # and one successful element are finite; longer chains are not.
        if isvar(a_rf) and isvar(b_rf):
            if allow_null:
                yield from nullo(a, b, default_ConsNull=null_type)(s)
            ca, cb = var(), var()
            for st in relation(ca, cb)(s):
                va, vb = reify((ca, cb), st)
                if null_type is etuple:
                    left, right = etuple(va), etuple(vb)
                elif null_type is tuple:
                    left, right = (va,), (vb,)
                else:
                    left, right = [va], [vb]
                yield from lall(eq(a, left), eq(b, right))(st)
            return

        yield from relational(s)

    return map_anyo_goal


def vararg_success(*args):
    return succeed


def eq_length(u, v, default_ConsNull=list):
    """Construct a goal stating that two sequences are the same length and type."""

    return mapo(vararg_success, u, v, null_type=default_ConsNull)


def _rebuild(src, rator, rands):
    """Preserve the original constructor when one argument is rewritten."""
    if type(src) is tuple:
        return (rator,) + tuple(rands)
    return etuple(rator, *rands)


def _one_rewrite(relation, src, dst):
    """``dst`` is ``src`` with ``relation`` applied at exactly one position.

    The root is a position, and so is every argument of a compound term.
    Siblings of the rewritten node are left unchanged.  A term no rule matches
    fails, so a fixed-point search can tell "no step" from "zero steps".
    """

    def goal(state):
        src_rf = reify(src, state)

        for st in relation(src, dst)(state):
            out = reify(dst, st)
            if not _is_noop(out, src_rf):
                yield st

        if isvar(src_rf) or not isinstance(src_rf, tuple) or len(src_rf) < 2:
            return

        rator = src_rf[0]
        children = list(src_rf[1:])
        for i, child in enumerate(children):
            if isvar(child) or not isinstance(child, tuple):
                # Atoms have no positions inside them.  Compound args do.
                if isvar(child) or isinstance(child, tuple):
                    pass
                else:
                    continue
            if not isinstance(child, tuple):
                continue
            child_out = var()
            for st in _one_rewrite(relation, child, child_out)(state):
                new_child = reify(child_out, st)
                if _is_noop(new_child, child):
                    continue
                new_children = list(children)
                new_children[i] = new_child
                built = _rebuild(src_rf, rator, new_children)
                if _is_noop(built, src_rf):
                    continue
                yield from eq(dst, built)(st)

    return goal


def _reachable(relation, start, state, limit=48):
    """Terms reachable in one or more applications of ``relation``.

    The start term is not included.  Each term is expanded once, so a
    reversible rule cannot run away.
    """

    seen = [start]
    found = []
    frontier = [start]
    budget = limit
    while frontier and budget > 0:
        nxt = []
        for term in frontier:
            mid = var()
            produced = 0
            for st in relation(term, mid)(state):
                val = reify(mid, st)
                produced += 1
                budget -= 1
                if produced > 32 or budget <= 0:
                    break
                if isvar(val) or _is_noop(val, term) or _seen(val, seen):
                    continue
                seen.append(val)
                nxt.append(val)
                if not _seen(val, found):
                    found.append(val)
            if budget <= 0:
                break
        frontier = nxt
    # Longer chains first so the fixed point precedes partial results.
    found.reverse()
    return found


def _preimages(relation, target, state, limit=8):
    """Distinct one-step preimages of a ground ``target``."""

    src = var()
    found = []
    for st in relation(src, target)(state):
        val = reify(src, st)
        if isvar(val) or _is_noop(val, target) or _seen(val, found):
            continue
        found.append(val)
        yield val
        if len(found) >= limit:
            return


def reduceo(relation, in_term, out_term, *args, **kwargs):
    """Relate a term to every term reachable under ``relation``.

    Forward mode needs at least one real rewrite.  The fixed point comes
    first, then shorter partial reductions.  A normal form (nothing rewrites)
    fails rather than answering with itself.

    Reverse mode (output ground, input unknown) yields shortest preimages
    first and does not answer with the unchanged term.
    """

    # Internal knobs from older callers are ignored.
    kwargs.pop("_seen", None)
    kwargs.pop("_expanding", None)
    kwargs.pop("_no_ident", None)

    def reduceo_goal(s):
        in_rf, out_rf = reify((in_term, out_term), s)

        if isvar(in_rf) and not isvar(out_rf):
            seen = [out_rf]
            frontier = [out_rf]
            depth = 0
            while frontier and depth < 16:
                depth += 1
                nxt = []
                for tgt in frontier:
                    for pre in _preimages(relation, tgt, s):
                        if _seen(pre, seen):
                            continue
                        seen.append(pre)
                        nxt.append(pre)
                        yield from eq(in_term, pre)(s)
                frontier = nxt
            return

        if isvar(in_rf):
            return

        for term in _reachable(relation, in_rf, s):
            yield from eq(out_term, term)(s)

    return reduceo_goal


def walko(
    goal,
    graph_in,
    graph_out,
    rator_goal=None,
    null_type=etuple,
    map_rel=partial(map_anyo, null_res=True),
):
    """Apply a binary relation between all nodes in two graphs.

    When `rator_goal` is used, the graphs are treated as term graphs, and the
    multi-functions `rator`, `rands`, and `apply` are used to walk the graphs.
    Otherwise, the graphs must be iterable according to `map_anyo`.

    Parameters
    ----------
    goal: callable
        A goal that is applied to all terms in the graph.
    graph_in: object
        The graph for which the left-hand side of a binary relation holds.
    graph_out: object
        The graph for which the right-hand side of a binary relation holds.
    rator_goal: callable (default None)
        A goal that is applied to the rators of a graph.  When specified,
        `goal` is only applied to rands and it must succeed along with the
        rator goal in order to descend into sub-terms.
    null_type: type
        The collection type used when it is not fully determined by the graph
        arguments.
    map_rel: callable
        The map relation used to apply `goal` to a sub-graph.
    """

    def walko_goal(s):

        nonlocal goal, rator_goal, graph_in, graph_out, null_type, map_rel

        graph_in_rf, graph_out_rf = reify((graph_in, graph_out), s)

        rator_in, rands_in, rator_out, rands_out = var(), var(), var(), var()

        _walko = partial(
            walko, goal, rator_goal=rator_goal, null_type=null_type, map_rel=map_rel
        )

        if rator_goal is None:
            descend_g = map_rel(_walko, graph_in_rf, graph_out_rf, null_type=null_type)
        else:
            descend_g = lall(
                applyo(rator_in, rands_in, graph_in_rf),
                applyo(rator_out, rands_out, graph_out_rf),
                rator_goal(rator_in, rator_out),
                map_rel(_walko, rands_in, rands_out, null_type=null_type),
            )

        g = conde(
            [Zzz(goal, graph_in_rf, graph_out_rf)],
            [descend_g],
        )

        yield from g(s)

    return walko_goal


_MISSING = object()


def term_walko(
    rator_goal,
    rands_goal,
    a,
    b=_MISSING,
    null_type=etuple,
    no_ident=False,
    format_step=None,
    **kwargs
):
    """Construct a goal for walking a term graph.

    ``term_walko(relation, in_term, out_term)`` on a ground term applies
    ``relation`` at exactly one position (the root or one subterm).  ``reduceo``
    repeats that to every partial reduction.  When the input is unknown and the
    output is ground, the same call yields shortest preimages of ``relation``.

    ``term_walko(rator_goal, rands_goal, a, b)`` walks operator terms for
    associative and commutative unification.

    XXX: Make sure `rator_goal` will succeed for unground logic variables;
    otherwise, this will diverge.
    XXX: `rands_goal` should not contain `eq`, i.e. `rands_goal(x, x)`
    should always fail!
    """

    if b is _MISSING or not callable(rands_goal):
        relation, in_term, out_term = rator_goal, rands_goal, a

        def walk_goal(state):
            in_rf, out_rf = reify((in_term, out_term), state)
            if isvar(in_rf) and not isvar(out_rf):
                # Un-reduced forms, shortest first.
                yield from reduceo(relation, in_term, out_term)(state)
            else:
                yield from _one_rewrite(relation, in_term, out_term)(state)

        return walk_goal

    def single_step(s, t):
        u, v = var(), var()
        u_rator, u_rands = var(), var()
        v_rands = var()

        return lall(
            ground_order((s, t), (u, v)),
            applyo(u_rator, u_rands, u),
            applyo(u_rator, v_rands, v),
            rator_goal(u_rator),
            # Non-empty rands.  Another ``conso`` leaves an open tail, so the
            # shortest associative regrouping is no longer three leaves.
            conso(var(), var(), u_rands),
            conso(var(), var(), v_rands),
            Zzz(rands_goal, u_rands, v_rands, u_rator, **kwargs),
            _neq(u, v),
        )

    def term_walko_step(s, t):
        nonlocal rator_goal, rands_goal, null_type
        u, v = var(), var()
        z, w = var(), var()

        def descend(state):
            goal = lall(
                Zzz(map_anyo, term_walko_step, w, z, null_type=null_type),
                conde([eq(z, v)], [single_step(z, v)]),
            )
            yield from goal(state)

        return lall(
            ground_order((s, t), (u, v)),
            format_step(u, w) if format_step is not None else eq(u, w),
            conde(
                [single_step(w, v)],
                [descend],
            ),
        )

    if no_ident:
        return term_walko_step(a, b)

    # Fair interleave: first regrouping, the original term, the next one.
    return conde([term_walko_step(a, b)], [eq(a, b)])

from functools import partial

from unification import var, isvar
from unification import reify, unify

from etuples import etuple

from .core import eq, conde, lall, succeed, Zzz, fail, ground_order
from .goals import conso, nullo
from .term import applyo


def _neq(u, v):
    """Succeed when ``u`` and ``v`` are observably different.

    Unbound values are allowed through so later goals can still ground them.
    """

    def neq_goal(s):
        u_rf, v_rf = reify((u, v), s)
        if isvar(u_rf) or isvar(v_rf):
            yield s
            return
        if unify(u_rf, v_rf, {}) is False:
            yield s

    return neq_goal


def _contains_var(term):
    if isvar(term):
        return True
    if isinstance(term, (list, tuple)):
        return any(_contains_var(x) for x in term)
    return False


def _same(a, b):
    try:
        return a == b
    except Exception:
        return False


def _is_noop(image, original):
    if isvar(image) or isvar(original):
        return False
    return _same(image, original)


def _seen(term, terms):
    return any(_same(term, item) for item in terms)


def _fair_gen(left, right):
    """Alternate two goal streams the way a fair ``conde`` does."""

    left, right = iter(left), iter(right)
    while True:
        try:
            yield next(left)
        except StopIteration:
            yield from right
            return
        try:
            yield next(right)
        except StopIteration:
            yield from left
            return


def _dedup(states, key):
    seen = []
    for state in states:
        value = reify(key, state)
        if _seen(value, seen):
            continue
        seen.append(value)
        yield state


def mapo(relation, a, b, null_type=list, null_res=True, first=True):
    """Apply a relation to corresponding elements in two sequences and succeed if the relation succeeds for all pairs."""

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    return conde(
        [nullo(a, b, default_ConsNull=null_type) if (not first or null_res) else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            Zzz(relation, a_car, b_car),
            Zzz(
                mapo,
                relation,
                a_cdr,
                b_cdr,
                null_type=null_type,
                null_res=null_res,
                first=False,
            ),
        ],
    )


def map_anyo(
    relation, a, b, null_type=list, null_res=False, first=True, any_succeed=False
):
    """Apply a relation to corresponding elements in two sequences and succeed if at least one pair succeeds.

    Parameters
    ----------
    null_type: optional
       An object that's a valid cdr for the collection type desired.  If
       `False` (i.e. the default value), the cdr will be inferred from the
       inputs, or defaults to an empty list.
    """

    def _empty():
        if isinstance(null_type, type):
            return null_type()
        return []

    def _forward(seq, out_var, s, any_succ, is_first):
        """Ground list to unknown list.

        Reproducing an element is not a successful step, so an identity
        reduction cannot make an unchanged collection succeed.
        """

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(out_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            b_car, b_cdr = var(), var()
            for s1 in relation(car, b_car)(s):
                if _is_noop(reify(b_car, s1), car):
                    continue
                for s2 in _forward(cdr, b_cdr, s1, True, False):
                    image = reify(b_car, s2)
                    tail = reify(b_cdr, s2)
                    if _is_noop(image, car) or not isinstance(tail, list):
                        continue
                    yield from eq(out_var, [image] + tail)(s)

        def eq_branch():
            b_car, b_cdr = var(), var()
            for s1 in eq(car, b_car)(s):
                for s2 in _forward(cdr, b_cdr, s1, any_succ, False):
                    image = reify(b_car, s2)
                    tail = reify(b_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(out_var, [image] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    def _reverse(seq, in_var, s, any_succ, is_first):
        """Known output list, unknown input list."""

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(in_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            a_car, a_cdr = var(), var()
            for s1 in relation(a_car, car)(s):
                if _is_noop(reify(a_car, s1), car):
                    continue
                for s2 in _reverse(cdr, a_cdr, s1, True, False):
                    image = reify(a_car, s2)
                    tail = reify(a_cdr, s2)
                    if _is_noop(image, car) or not isinstance(tail, list):
                        continue
                    yield from eq(in_var, [image] + tail)(s)

        def eq_branch():
            a_car, a_cdr = var(), var()
            for s1 in eq(a_car, car)(s):
                for s2 in _reverse(cdr, a_cdr, s1, any_succ, False):
                    image = reify(a_car, s2)
                    tail = reify(a_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(in_var, [image] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()
    allow_null = any_succeed or (first and null_res)

    relational = conde(
        [nullo(a, b, default_ConsNull=null_type) if allow_null else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            conde(
                [
                    Zzz(relation, a_car, b_car),
                    # The step succeeded, so the remaining tail may be empty.
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=True,
                    ),
                ],
                [
                    eq(a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=any_succeed,
                    ),
                ],
            ),
        ],
    )

    def map_anyo_goal(s):
        a_rf, b_rf = reify((a, b), s)

        if type(a_rf) is list and not _contains_var(a_rf):
            yield from _dedup(_forward(a_rf, b, s, any_succeed, first), b)
            return

        if isvar(a_rf) and type(b_rf) is list and not _contains_var(b_rf):
            yield from _dedup(_reverse(b_rf, a, s, any_succeed, first), a)
            return

        # Fresh sequences have no finite longest answer.  Empty (when allowed)
        # and a single successful element are finite; longer chains are not.
        if isvar(a_rf) and isvar(b_rf):
            if allow_null:
                yield from nullo(a, b, default_ConsNull=null_type)(s)
            ca, cb = var(), var()
            for st in relation(ca, cb)(s):
                va, vb = reify((ca, cb), st)
                if null_type is etuple:
                    left, right = etuple(va), etuple(vb)
                elif null_type is tuple:
                    left, right = (va,), (vb,)
                else:
                    left, right = [va], [vb]
                yield from lall(eq(a, left), eq(b, right))(st)
            return

        yield from relational(s)

    return map_anyo_goal


def vararg_success(*args):
    return succeed


def eq_length(u, v, default_ConsNull=list):
    """Construct a goal stating that two sequences are the same length and type."""

    return mapo(vararg_success, u, v, null_type=default_ConsNull)


def _rebuild(src, rator, rands):
    if type(src) is tuple:
        return (rator,) + tuple(rands)
    return etuple(rator, *rands)


def _one_rewrite(relation, src, dst, _depth=0):
    """Apply ``relation`` at exactly one position of a ground term.

    Positions are the root and every compound argument.  Nothing is rewritten
    inside an atom, and a term no rule matches fails.
    """

    def goal(state):
        if _depth > 16:
            return
        src_rf = reify(src, state)
        if isvar(src_rf):
            return

        produced = 0
        for st in relation(src_rf, dst)(state):
            out = reify(dst, st)
            produced += 1
            if produced > 8:
                break
            if not _is_noop(out, src_rf):
                yield st

        if not isinstance(src_rf, tuple) or len(src_rf) < 2:
            return

        rator = src_rf[0]
        children = list(src_rf[1:])
        for i, child in enumerate(children):
            if isvar(child) or not isinstance(child, tuple):
                continue
            if len(child) >= len(src_rf) and _same(child, src_rf):
                continue
            child_out = var()
            child_n = 0
            for st in _one_rewrite(relation, child, child_out, _depth + 1)(state):
                child_n += 1
                if child_n > 8:
                    break
                new_child = reify(child_out, st)
                if isvar(new_child) or _is_noop(new_child, child):
                    continue
                new_children = list(children)
                new_children[i] = new_child
                built = _rebuild(src_rf, rator, new_children)
                if _is_noop(built, src_rf):
                    continue
                yield from eq(dst, built)(st)

    return goal


def _preimages(relation, target, state, limit=4):
    """A few distinct one-step preimages of a ground target."""

    src = var()
    found = []
    try:
        stream = relation(src, target)(state)
    except TypeError:
        return
    for st in stream:
        val = reify(src, st)
        if isvar(val) or _is_noop(val, target) or _seen(val, found):
            continue
        found.append(val)
        yield val
        if len(found) >= limit:
            return


def reduceo(relation, in_term, out_term, *args, _seen=(), **kwargs):
    """Iterate a one-step relation.

    Forward mode yields every term reachable in one or more real rewrites,
    longest chains first.  A normal form fails: the original term is not an
    answer when no rule applies.

    Reverse mode (output ground, input unknown) yields shortest preimages
    first and does not answer with the unchanged term.
    """

    kwargs.pop("_expanding", None)
    kwargs.pop("_no_ident", None)

    def reduceo_goal(s):
        if len(_seen) > 8:
            return

        in_rf, out_rf = reify((in_term, out_term), s)

        if isvar(in_rf) and not isvar(out_rf):
            # One level at a time, so the first answers are the shortest.
            seen = [out_rf]
            frontier = [out_rf]
            depth = 0
            while frontier and depth < 4:
                depth += 1
                nxt = []
                for tgt in list(frontier):
                    for pre in _preimages(relation, tgt, s):
                        if _seen(pre, seen):
                            continue
                        seen.append(pre)
                        nxt.append(pre)
                        yield from eq(in_term, pre)(s)
                frontier = nxt
            return

        if isvar(in_rf) or _seen(in_rf, _seen):
            return

        new_seen = _seen + (in_rf,)
        mid = var()
        # Deeper rewrites before the one-step result, so the fixed point is
        # first.  No zero-step identity: the step goal has to succeed.
        deeper = Zzz(
            reduceo, relation, mid, out_term, _seen=new_seen
        )
        step = Zzz(relation, in_rf, mid)
        changed = _neq(in_rf, mid)
        # ``_neq`` allows variables; require a ground, different mid.
        def changed_ground(state):
            left, right = reify((in_rf, mid), state)
            if isvar(left) or isvar(right) or _same(left, right):
                return
            yield state

        g = lall(step, changed_ground, conde([deeper], [eq(mid, out_term)]))
        yield from g(s)

    return reduceo_goal


def walko(
    goal,
    graph_in,
    graph_out,
    rator_goal=None,
    null_type=etuple,
    map_rel=partial(map_anyo, null_res=True),
):
    """Apply a binary relation between all nodes in two graphs.

    When `rator_goal` is used, the graphs are treated as term graphs, and the
    multi-functions `rator`, `rands`, and `apply` are used to walk the graphs.
    Otherwise, the graphs must be iterable according to `map_anyo`.

    Parameters
    ----------
    goal: callable
        A goal that is applied to all terms in the graph.
    graph_in: object
        The graph for which the left-hand side of a binary relation holds.
    graph_out: object
        The graph for which the right-hand side of a binary relation holds.
    rator_goal: callable (default None)
        A goal that is applied to the rators of a graph.  When specified,
        `goal` is only applied to rands and it must succeed along with the
        rator goal in order to descend into sub-terms.
    null_type: type
        The collection type used when it is not fully determined by the graph
        arguments.
    map_rel: callable
        The map relation used to apply `goal` to a sub-graph.
    """

    def walko_goal(s):

        nonlocal goal, rator_goal, graph_in, graph_out, null_type, map_rel

        graph_in_rf, graph_out_rf = reify((graph_in, graph_out), s)

        rator_in, rands_in, rator_out, rands_out = var(), var(), var(), var()

        _walko = partial(
            walko, goal, rator_goal=rator_goal, null_type=null_type, map_rel=map_rel
        )

        if rator_goal is None:
            descend_g = map_rel(_walko, graph_in_rf, graph_out_rf, null_type=null_type)
        else:
            descend_g = lall(
                applyo(rator_in, rands_in, graph_in_rf),
                applyo(rator_out, rands_out, graph_out_rf),
                rator_goal(rator_in, rator_out),
                map_rel(_walko, rands_in, rands_out, null_type=null_type),
            )

        g = conde(
            [Zzz(goal, graph_in_rf, graph_out_rf)],
            [descend_g],
        )

        yield from g(s)

    return walko_goal


_MISSING = object()


def term_walko(
    rator_goal,
    rands_goal,
    a,
    b=_MISSING,
    null_type=etuple,
    no_ident=False,
    format_step=None,
    **kwargs
):
    """Construct a goal for walking a term graph.

    ``term_walko(relation, in_term, out_term)`` applies ``relation`` at one
    position of a ground term.  ``reduceo`` repeats that.  With the input
    unknown and the output ground, it yields shortest preimages instead.

    ``term_walko(rator_goal, rands_goal, a, b)`` walks operator terms for
    associative and commutative unification.

    XXX: Make sure `rator_goal` will succeed for unground logic variables;
    otherwise, this will diverge.
    XXX: `rands_goal` should not contain `eq`, i.e. `rands_goal(x, x)`
    should always fail!
    """

    if b is _MISSING or not callable(rands_goal):
        relation, in_term, out_term = rator_goal, rands_goal, a

        def walk_goal(state):
            in_rf, out_rf = reify((in_term, out_term), state)
            if isvar(in_rf) and not isvar(out_rf):
                yield from reduceo(relation, in_term, out_term)(state)
            else:
                yield from _one_rewrite(relation, in_term, out_term)(state)

        return walk_goal

    def single_step(s, t):
        u, v = var(), var()
        u_rator, u_rands = var(), var()
        v_rands = var()

        return lall(
            ground_order((s, t), (u, v)),
            applyo(u_rator, u_rands, u),
            applyo(u_rator, v_rands, v),
            rator_goal(u_rator),
            # Non-empty rands.  A second ``conso`` leaves an open tail and the
            # shortest associative regrouping stops being three leaves.
            conso(var(), var(), u_rands),
            conso(var(), var(), v_rands),
            Zzz(rands_goal, u_rands, v_rands, u_rator, **kwargs),
            _neq(u, v),
        )

    def term_walko_step(s, t):
        nonlocal rator_goal, rands_goal, null_type
        u, v = var(), var()
        z, w = var(), var()

        def descend(state):
            goal = lall(
                Zzz(map_anyo, term_walko_step, w, z, null_type=null_type),
                conde([eq(z, v)], [single_step(z, v)]),
            )
            yield from goal(state)

        return lall(
            ground_order((s, t), (u, v)),
            format_step(u, w) if format_step is not None else eq(u, w),
            conde(
                [single_step(w, v)],
                [descend],
            ),
        )

    if no_ident:
        return term_walko_step(a, b)

    # Fair interleave: first regrouping, the original term, the next one.
    return conde([term_walko_step(a, b)], [eq(a, b)])

from functools import partial

from unification import var, isvar
from unification import reify, unify

from etuples import etuple

from .core import eq, conde, lall, succeed, Zzz, fail, ground_order
from .goals import conso, nullo
from .term import applyo


def _neq(u, v):
    """Succeed when ``u`` and ``v`` are observably different.

    Unbound values are allowed through so a later goal can still ground them.
    """

    def neq_goal(s):
        u_rf, v_rf = reify((u, v), s)
        if isvar(u_rf) or isvar(v_rf):
            yield s
            return
        if unify(u_rf, v_rf, {}) is False:
            yield s

    return neq_goal


def _contains_var(term):
    if isvar(term):
        return True
    if isinstance(term, (list, tuple)):
        return any(_contains_var(x) for x in term)
    return False


def _same(a, b):
    try:
        return a == b
    except Exception:
        return False


def _is_noop(image, original):
    if isvar(image) or isvar(original):
        return False
    return _same(image, original)


def _has(term, terms):
    """Membership that does not require the term to be hashable."""
    return any(_same(term, item) for item in terms)


def _fair_gen(left, right):
    """Alternate two goal streams the way a fair ``conde`` does."""

    left, right = iter(left), iter(right)
    while True:
        try:
            yield next(left)
        except StopIteration:
            yield from right
            return
        try:
            yield next(right)
        except StopIteration:
            yield from left
            return


def mapo(relation, a, b, null_type=list, null_res=True, first=True):
    """Apply a relation to corresponding elements in two sequences and succeed if the relation succeeds for all pairs."""

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    return conde(
        [nullo(a, b, default_ConsNull=null_type) if (not first or null_res) else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            Zzz(relation, a_car, b_car),
            Zzz(
                mapo,
                relation,
                a_cdr,
                b_cdr,
                null_type=null_type,
                null_res=null_res,
                first=False,
            ),
        ],
    )


def map_anyo(
    relation, a, b, null_type=list, null_res=False, first=True, any_succeed=False
):
    """Apply a relation to corresponding elements in two sequences and succeed if at least one pair succeeds.

    Parameters
    ----------
    null_type: optional
       An object that's a valid cdr for the collection type desired.  If
       `False` (i.e. the default value), the cdr will be inferred from the
       inputs, or defaults to an empty list.
    """

    def _empty():
        if isinstance(null_type, type):
            return null_type()
        return []

    def _forward(seq, out_var, s, any_succ, is_first):
        """Ground list to unknown (or equally ground) list.

        Every successful application counts, even when the value does not
        change.  ``map_anyo(eq, xs, xs)`` is one success per non-empty subset
        of positions, and those duplicates are observable.
        """

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(out_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            b_car, b_cdr = var(), var()
            for s1 in relation(car, b_car)(s):
                image = reify(b_car, s1)
                for s2 in _forward(cdr, b_cdr, s1, True, False):
                    tail = reify(b_cdr, s2)
                    if isinstance(tail, list):
                        # ``s``, not ``s2``: ``out_var`` must not keep a binding
                        # left behind by an earlier answer.
                        yield from eq(out_var, [image] + tail)(s)

        def eq_branch():
            for s2 in _forward(cdr, var(), s, any_succ, False):
                tail = reify(var(), s2) if False else None
                # Re-read the tail var actually threaded above.
                pass
            b_cdr = var()
            for s2 in _forward(cdr, b_cdr, s, any_succ, False):
                tail = reify(b_cdr, s2)
                if isinstance(tail, list):
                    yield from eq(out_var, [car] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    def _reverse(seq, in_var, s, any_succ, is_first):
        """Known output list, unknown input list."""

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(in_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            a_car, a_cdr = var(), var()
            for s1 in relation(a_car, car)(s):
                image = reify(a_car, s1)
                for s2 in _reverse(cdr, a_cdr, s1, True, False):
                    tail = reify(a_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(in_var, [image] + tail)(s)

        def eq_branch():
            a_cdr = var()
            for s2 in _reverse(cdr, a_cdr, s, any_succ, False):
                tail = reify(a_cdr, s2)
                if isinstance(tail, list):
                    yield from eq(in_var, [car] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()
    allow_null = any_succeed or (first and null_res)

    relational = conde(
        [nullo(a, b, default_ConsNull=null_type) if allow_null else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            conde(
                [
                    Zzz(relation, a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=True,
                    ),
                ],
                [
                    eq(a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=any_succeed,
                    ),
                ],
            ),
        ],
    )

    def map_anyo_goal(s):
        a_rf, b_rf = reify((a, b), s)

        if type(a_rf) is list and not _contains_var(a_rf):
            # No dedup: identical lists from different subsets are distinct
            # answers (see ``map_anyo(eq, [1, 2, 3], [1, 2, 3])`` -> 7).
            yield from _forward(a_rf, b, s, any_succeed, first)
            return

        if isvar(a_rf) and type(b_rf) is list and not _contains_var(b_rf):
            yield from _reverse(b_rf, a, s, any_succeed, first)
            return

        # Fresh sequences have no finite longest answer.  Empty (when allowed)
        # and one successful element are finite; longer chains are not.
        if isvar(a_rf) and isvar(b_rf):
            if allow_null:
                yield from nullo(a, b, default_ConsNull=null_type)(s)
            ca, cb = var(), var()
            for st in relation(ca, cb)(s):
                va, vb = reify((ca, cb), st)
                if null_type is etuple:
                    left, right = etuple(va), etuple(vb)
                elif null_type is tuple:
                    left, right = (va,), (vb,)
                else:
                    left, right = [va], [vb]
                yield from lall(eq(a, left), eq(b, right))(st)
            return

        yield from relational(s)

    return map_anyo_goal


