            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            a_car, a_cdr = var(), var()
            for s1 in relation(a_car, car)(s):
                image = reify(a_car, s1)
                for s2 in _reverse(cdr, a_cdr, s1, True, False):
                    tail = reify(a_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(in_var, [image] + tail)(s)

        def eq_branch():
            a_cdr = var()
            for s2 in _reverse(cdr, a_cdr, s, any_succ, False):
                tail = reify(a_cdr, s2)
                if isinstance(tail, list):
                    yield from eq(in_var, [car] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()
    allow_null = any_succeed or (first and null_res)

    relational = conde(
        [nullo(a, b, default_ConsNull=null_type) if allow_null else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            conde(
                [
                    Zzz(relation, a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=True,
                    ),
                ],
                [
                    eq(a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=any_succeed,
                    ),
                ],
            ),
        ],
    )

    def map_anyo_goal(s):
        a_rf, b_rf = reify((a, b), s)

        if type(a_rf) is list and not _contains_var(a_rf):
            yield from _forward(a_rf, b, s, any_succeed, first)
            return

        if isvar(a_rf) and type(b_rf) is list and not _contains_var(b_rf):
            yield from _reverse(b_rf, a, s, any_succeed, first)
            return

        # One element is the finite answer when nothing fixes the length.
        # Only the first relation result is taken: asking for another re-enters
        # this same unconstrained walk.
        if isvar(a_rf) and isvar(b_rf):
            if allow_null:
                yield from nullo(a, b, default_ConsNull=null_type)(s)
            ca, cb = var(), var()
            stream = relation(ca, cb)(s)
            try:
                st = next(stream)
            except StopIteration:
                return
            va, vb = reify((ca, cb), st)
            yield from lall(
                eq(a, _singleton(va)),
                eq(b, _singleton(vb)),
            )(st)
            return

        yield from relational(s)

    return map_anyo_goal


def vararg_success(*args):
    return succeed


def eq_length(u, v, default_ConsNull=list):
    """Construct a goal stating that two sequences are the same length and type."""

    return mapo(vararg_success, u, v, null_type=default_ConsNull)


def _rebuild(src, rator, rands):
    if type(src) is tuple:
        return (rator,) + tuple(rands)
    return etuple(rator, *rands)


def _one_rewrite(relation, src, dst, _depth=0):
    """``dst`` is ``src`` with ``relation`` applied at exactly one position.

    The root counts, and so does any argument of a compound term.  A term no
    rule matches fails, so the fixed-point search can tell "no step" apart
    from "zero steps".
    """

    def goal(state):
        if _depth > 24:
            return
        src_rf = reify(src, state)
        if isvar(src_rf):
            return

        produced = 0
        for st in relation(src_rf, dst)(state):
            produced += 1
            if produced > 16:
                break
            out = reify(dst, st)
            if not _is_noop(out, src_rf):
                yield st

        if not isinstance(src_rf, tuple) or len(src_rf) < 2:
            return

        rator = src_rf[0]
        children = list(src_rf[1:])
        for i, child in enumerate(children):
            child_out = var()
            child_n = 0
            for st in _one_rewrite(relation, child, child_out, _depth + 1)(state):
                child_n += 1
                if child_n > 16:
                    break
                new_child = reify(child_out, st)
                if isvar(new_child) or _is_noop(new_child, child):
                    continue
                new_children = list(children)
                new_children[i] = new_child
                built = _rebuild(src_rf, rator, new_children)
                if _is_noop(built, src_rf):
                    continue
                yield from eq(dst, built)(st)

    return goal


def _preimages(relation, target, state, limit=8):
    """Distinct one-step preimages of a ground target."""

    src = var()
    found = []
    try:
        stream = relation(src, target)(state)
    except TypeError:
        return
    for st in stream:
        val = reify(src, st)
        if isvar(val) or _is_noop(val, target) or _has(val, found):
            continue
        found.append(val)
        yield val
        if len(found) >= limit:
            return


def _chain(relation, term, state, stack, depth):
    """Terms reachable in one or more rewrites, longer chains first."""

    if depth > 12:
        return []
    mid = var()
    steps = []
    n = 0
    try:
        stream = relation(term, mid)(state)
    except TypeError:
        return []
    for st in stream:
        n += 1
        if n > 32:
            break
        val = reify(mid, st)
        if isvar(val) or _is_noop(val, term) or _has(val, steps) or _has(val, stack):
            continue
        steps.append(val)

    out = []
    for nxt in steps:
        for item in _chain(relation, nxt, state, stack + (term,), depth + 1):
            if not _has(item, out):
                out.append(item)
        if not _has(nxt, out):
            out.append(nxt)
    return out


def reduceo(relation, in_term, out_term, *args, **kwargs):
    """Iterate a one-step relation.

    Forward mode yields every term reachable in one or more real rewrites,
    longest chains first.  A normal form fails instead of answering with
    itself.

    Reverse mode (output ground, input unknown) yields shortest preimages
    first and does not answer with the unchanged term.
    """

    kwargs.pop("_seen", None)
    kwargs.pop("_expanding", None)
    kwargs.pop("_no_ident", None)

    def reduceo_goal(s):
        in_rf, out_rf = reify((in_term, out_term), s)

        if isvar(in_rf) and not isvar(out_rf):
            seen = [out_rf]
            frontier = [out_rf]
            depth = 0
            while frontier and depth < 6:
                depth += 1
                nxt = []
                for tgt in frontier:
                    for pre in _preimages(relation, tgt, s):
                        if _has(pre, seen):
                            continue
                        seen.append(pre)
                        nxt.append(pre)
                        yield from eq(in_term, pre)(s)
                frontier = nxt
            return

        if isvar(in_rf):
            return

        for term in _chain(relation, in_rf, s, (), 0):
            yield from eq(out_term, term)(s)

    return reduceo_goal


def walko(
    goal,
    graph_in,
    graph_out,
    rator_goal=None,
    null_type=etuple,
    map_rel=partial(map_anyo, null_res=True),
):
    """Apply a binary relation between all nodes in two graphs.

    When `rator_goal` is used, the graphs are treated as term graphs, and the
    multi-functions `rator`, `rands`, and `apply` are used to walk the graphs.
    Otherwise, the graphs must be iterable according to `map_anyo`.

    Parameters
    ----------
    goal: callable
        A goal that is applied to all terms in the graph.
    graph_in: object
        The graph for which the left-hand side of a binary relation holds.
    graph_out: object
        The graph for which the right-hand side of a binary relation holds.
    rator_goal: callable (default None)
        A goal that is applied to the rators of a graph.  When specified,
        `goal` is only applied to rands and it must succeed along with the
        rator goal in order to descend into sub-terms.
    null_type: type
        The collection type used when it is not fully determined by the graph
        arguments.
    map_rel: callable
        The map relation used to apply `goal` to a sub-graph.
    """

    def walko_goal(s):

        nonlocal goal, rator_goal, graph_in, graph_out, null_type, map_rel

        graph_in_rf, graph_out_rf = reify((graph_in, graph_out), s)

        # No ground shape to follow.  Descending builds fresh rands and walks
        # them again, which recurses until ``cons`` overflows the stack.
        if isvar(graph_in_rf) and isvar(graph_out_rf):
            yield from goal(graph_in_rf, graph_out_rf)(s)
            return

        rator_in, rands_in, rator_out, rands_out = var(), var(), var(), var()

        _walko = partial(
            walko, goal, rator_goal=rator_goal, null_type=null_type, map_rel=map_rel
        )

        if rator_goal is None:
            descend_g = map_rel(_walko, graph_in_rf, graph_out_rf, null_type=null_type)
        else:
            descend_g = lall(
                applyo(rator_in, rands_in, graph_in_rf),
                applyo(rator_out, rands_out, graph_out_rf),
                rator_goal(rator_in, rator_out),
                map_rel(_walko, rands_in, rands_out, null_type=null_type),
            )

        g = conde(
            [Zzz(goal, graph_in_rf, graph_out_rf)],
            [descend_g],
        )

        yield from g(s)

    return walko_goal


_MISSING = object()


def term_walko(
    rator_goal,
    rands_goal,
    a,
    b=_MISSING,
    null_type=etuple,
    no_ident=False,
    format_step=None,
    **kwargs
):
    """Construct a goal for walking a term graph.

    ``term_walko(relation, in_term, out_term)`` applies ``relation`` at one
    position of a ground term (the root or one subterm).  ``reduceo`` repeats
    that.  When the input is unknown and the output is ground, the same call
    yields shortest preimages of ``relation``.

    ``term_walko(rator_goal, rands_goal, a, b)`` walks operator terms for
    associative and commutative unification.

    XXX: Make sure `rator_goal` will succeed for unground logic variables;
    otherwise, this will diverge.
    XXX: `rands_goal` should not contain `eq`, i.e. `rands_goal(x, x)`
    should always fail!
    """

    if b is _MISSING or not callable(rands_goal):
        relation, in_term, out_term = rator_goal, rands_goal, a

        def walk_goal(state):
            in_rf, out_rf = reify((in_term, out_term), state)
            if isvar(in_rf) and not isvar(out_rf):
                yield from reduceo(relation, in_term, out_term)(state)
            else:
                yield from _one_rewrite(relation, in_term, out_term)(state)

        return walk_goal

    def single_step(s, t):
        u, v = var(), var()
        u_rator, u_rands = var(), var()
        v_rands = var()

        return lall(
            ground_order((s, t), (u, v)),
            applyo(u_rator, u_rands, u),
            applyo(u_rator, v_rands, v),
            rator_goal(u_rator),
            Zzz(rands_goal, u_rands, v_rands, u_rator, **kwargs),
            _nonempty(u_rands),
            _nonempty(v_rands),
            _neq(u, v),
        )

    def term_walko_step(s, t):
        nonlocal rator_goal, rands_goal, null_type
        u, v = var(), var()
        z, w = var(), var()

        def descend(state):
            goal = lall(
                Zzz(map_anyo, term_walko_step, w, z, null_type=null_type),
                conde([eq(z, v)], [single_step(z, v)]),
            )
            yield from goal(state)

        return lall(
            ground_order((s, t), (u, v)),
            format_step(u, w) if format_step is not None else eq(u, w),
            conde(
                [single_step(w, v)],
                [descend],
            ),
        )

    if no_ident:
        return term_walko_step(a, b)

    # Fair interleave: first regrouping, the original term, the next one.
    return conde([term_walko_step(a, b)], [eq(a, b)])

from functools import partial

from unification import var, isvar
from unification import reify, unify

from etuples import etuple

from .core import eq, conde, lall, succeed, Zzz, fail, ground_order
from .goals import conso, nullo
from .term import applyo


def _neq(u, v):
    """Succeed when ``u`` and ``v`` are observably different.

    Unbound values are allowed through so a later goal can still ground them.
    """

    def neq_goal(s):
        u_rf, v_rf = reify((u, v), s)
        if isvar(u_rf) or isvar(v_rf):
            yield s
            return
        if unify(u_rf, v_rf, {}) is False:
            yield s

    return neq_goal


def _contains_var(term):
    if isvar(term):
        return True
    if isinstance(term, (list, tuple)):
        return any(_contains_var(x) for x in term)
    return False


def _same(a, b):
    try:
        return a == b
    except Exception:
        return False


def _is_noop(image, original):
    if isvar(image) or isvar(original):
        return False
    return _same(image, original)


def _has(term, terms):
    """Membership that does not require the term to be hashable."""
    return any(_same(term, item) for item in terms)


def _nonempty(seq):
    """Fail only when ``seq`` is already a ground empty collection.

    A logic variable is left alone.  ``conso`` would build an open tail here,
    and an associative step then answers with one leaf too many.
    """

    def goal(state):
        rf = reify(seq, state)
        if isvar(rf):
            yield state
            return
        if isinstance(rf, (list, tuple)) and len(rf) == 0:
            return
        yield state

    return goal


def _fair_gen(left, right):
    """Alternate two goal streams the way a fair ``conde`` does."""

    left, right = iter(left), iter(right)
    while True:
        try:
            yield next(left)
        except StopIteration:
            yield from right
            return
        try:
            yield next(right)
        except StopIteration:
            yield from left
            return


def mapo(relation, a, b, null_type=list, null_res=True, first=True):
    """Apply a relation to corresponding elements in two sequences and succeed if the relation succeeds for all pairs."""

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    return conde(
        [nullo(a, b, default_ConsNull=null_type) if (not first or null_res) else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            Zzz(relation, a_car, b_car),
            Zzz(
                mapo,
                relation,
                a_cdr,
                b_cdr,
                null_type=null_type,
                null_res=null_res,
                first=False,
            ),
        ],
    )


def map_anyo(
    relation, a, b, null_type=list, null_res=False, first=True, any_succeed=False
):
    """Apply a relation to corresponding elements in two sequences and succeed if at least one pair succeeds.

    Parameters
    ----------
    null_type: optional
       An object that's a valid cdr for the collection type desired.  If
       `False` (i.e. the default value), the cdr will be inferred from the
       inputs, or defaults to an empty list.
    """

    def _empty():
        if isinstance(null_type, type):
            return null_type()
        return []

    def _singleton(value):
        if null_type is etuple:
            return etuple(value)
        if null_type is tuple:
            return (value,)
        return [value]

    def _forward(seq, out_var, s, any_succ, is_first):
        """Ground list to unknown (or equally ground) list.

        Every successful application counts, even when the value does not
        change.  ``map_anyo(eq, xs, xs)`` is one success per non-empty subset
        of positions.
        """

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(out_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            b_car, b_cdr = var(), var()
            for s1 in relation(car, b_car)(s):
                image = reify(b_car, s1)
                for s2 in _forward(cdr, b_cdr, s1, True, False):
                    tail = reify(b_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(out_var, [image] + tail)(s)

        def eq_branch():
            b_cdr = var()
            for s2 in _forward(cdr, b_cdr, s, any_succ, False):
                tail = reify(b_cdr, s2)
                if isinstance(tail, list):
                    yield from eq(out_var, [car] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    def _reverse(seq, in_var, s, any_succ, is_first):
        """Known output list, unknown input list."""

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(in_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            a_car, a_cdr = var(), var()
            for s1 in relation(a_car, car)(s):
                image = reify(a_car, s1)
                for s2 in _reverse(cdr, a_cdr, s1, True, False):
                    tail = reify(a_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(in_var, [image] + tail)(s)

        def eq_branch():
            a_cdr = var()
            for s2 in _reverse(cdr, a_cdr, s, any_succ, False):
                tail = reify(a_cdr, s2)
                if isinstance(tail, list):
                    yield from eq(in_var, [car] + tail)(s)

        yield from _fair_gen(rel_branch(), eq_branch())

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()
    allow_null = any_succeed or (first and null_res)

    relational = conde(
        [nullo(a, b, default_ConsNull=null_type) if allow_null else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            conde(
                [
                    Zzz(relation, a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=True,
                    ),
                ],
                [
                    eq(a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=any_succeed,
                    ),
                ],
            ),
        ],
    )

    def map_anyo_goal(s):
        a_rf, b_rf = reify((a, b), s)

        if type(a_rf) is list and not _contains_var(a_rf):
            yield from _forward(a_rf, b, s, any_succeed, first)
            return

        if isvar(a_rf) and type(b_rf) is list and not _contains_var(b_rf):
            yield from _reverse(b_rf, a, s, any_succeed, first)
            return

        # One element is the finite answer when nothing fixes the length.
        # Only the first relation result is taken: asking for another re-enters
        # this same unconstrained walk.
        if isvar(a_rf) and isvar(b_rf):
            if allow_null:
                yield from nullo(a, b, default_ConsNull=null_type)(s)
            ca, cb = var(), var()
            stream = relation(ca, cb)(s)
            try:
                st = next(stream)
            except StopIteration:
                return
            va, vb = reify((ca, cb), st)
            yield from lall(
                eq(a, _singleton(va)),
                eq(b, _singleton(vb)),
            )(st)
            return

        yield from relational(s)

    return map_anyo_goal


def vararg_success(*args):
    return succeed


def eq_length(u, v, default_ConsNull=list):
    """Construct a goal stating that two sequences are the same length and type."""

    return mapo(vararg_success, u, v, null_type=default_ConsNull)


def _rebuild(src, rator, rands):
    if type(src) is tuple:
        return (rator,) + tuple(rands)
    return etuple(rator, *rands)


def _one_rewrite(relation, src, dst, _depth=0):
    """``dst`` is ``src`` with ``relation`` applied at exactly one position.

    The root counts, and so does any argument of a compound term.  A term no
    rule matches fails, so the fixed-point search can tell "no step" apart
    from "zero steps".
    """

    def goal(state):
        if _depth > 24:
            return
        src_rf = reify(src, state)
        if isvar(src_rf):
            return

        produced = 0
        for st in relation(src_rf, dst)(state):
            produced += 1
            if produced > 16:
                break
            out = reify(dst, st)
            if not _is_noop(out, src_rf):
                yield st

        if not isinstance(src_rf, tuple) or len(src_rf) < 2:
            return

        rator = src_rf[0]
        children = list(src_rf[1:])
        for i, child in enumerate(children):
            child_out = var()
            child_n = 0
            for st in _one_rewrite(relation, child, child_out, _depth + 1)(state):
                child_n += 1
                if child_n > 16:
                    break
                new_child = reify(child_out, st)
                if isvar(new_child) or _is_noop(new_child, child):
                    continue
                new_children = list(children)
                new_children[i] = new_child
                built = _rebuild(src_rf, rator, new_children)
                if _is_noop(built, src_rf):
                    continue
                yield from eq(dst, built)(st)

    return goal


def _preimages(relation, target, state, limit=8):
    """Distinct one-step preimages of a ground target."""

    src = var()
    found = []
    try:
        stream = relation(src, target)(state)
    except TypeError:
        return
    for st in stream:
        val = reify(src, st)
        if isvar(val) or _is_noop(val, target) or _has(val, found):
            continue
        found.append(val)
        yield val
        if len(found) >= limit:
            return


def _chain(relation, term, state, stack, depth):
    """Terms reachable in one or more rewrites, longer chains first."""

    if depth > 12:
        return []
    mid = var()
    steps = []
    n = 0
    try:
        stream = relation(term, mid)(state)
    except TypeError:
        return []
    for st in stream:
        n += 1
        if n > 32:
            break
        val = reify(mid, st)
        if isvar(val) or _is_noop(val, term) or _has(val, steps) or _has(val, stack):
            continue
        steps.append(val)

    out = []
    for nxt in steps:
        for item in _chain(relation, nxt, state, stack + (term,), depth + 1):
            if not _has(item, out):
                out.append(item)
        if not _has(nxt, out):
            out.append(nxt)
    return out


def reduceo(relation, in_term, out_term, *args, **kwargs):
    """Iterate a one-step relation.

    Forward mode yields every term reachable in one or more real rewrites,
    longest chains first.  A normal form fails instead of answering with
    itself.

    Reverse mode (output ground, input unknown) yields a depth-first chain of
    preimages: the first one-step answer, then its preimages, and only then
    the next sibling.  The unchanged term is not an answer.
    """

    kwargs.pop("_seen", None)
    kwargs.pop("_expanding", None)
    kwargs.pop("_no_ident", None)

    def reduceo_goal(s):
        in_rf, out_rf = reify((in_term, out_term), s)

        if isvar(in_rf) and not isvar(out_rf):
            # Depth-first so ``add(1, 1)`` is expanded to
            # ``log(exp(add(1, 1)))`` before the sibling ``log(exp(mul(2, 1)))``.
            seen = [out_rf]

            def expand(target, depth):
                if depth <= 0:
                    return
                for pre in _preimages(relation, target, s):
                    if _has(pre, seen):
                        continue
                    seen.append(pre)
                    yield pre
                    yield from expand(pre, depth - 1)

            for pre in expand(out_rf, 32):
                yield from eq(in_term, pre)(s)
            return

        if isvar(in_rf):
            return

        for term in _chain(relation, in_rf, s, (), 0):
            yield from eq(out_term, term)(s)

    return reduceo_goal


def walko(
    goal,
    graph_in,
    graph_out,
    rator_goal=None,
    null_type=etuple,
    map_rel=partial(map_anyo, null_res=True),
):
    """Apply a binary relation between all nodes in two graphs.

    When `rator_goal` is used, the graphs are treated as term graphs, and the
    multi-functions `rator`, `rands`, and `apply` are used to walk the graphs.
    Otherwise, the graphs must be iterable according to `map_anyo`.

    Parameters
    ----------
    goal: callable
        A goal that is applied to all terms in the graph.
    graph_in: object
        The graph for which the left-hand side of a binary relation holds.
    graph_out: object
        The graph for which the right-hand side of a binary relation holds.
    rator_goal: callable (default None)
        A goal that is applied to the rators of a graph.  When specified,
        `goal` is only applied to rands and it must succeed along with the
        rator goal in order to descend into sub-terms.
    null_type: type
        The collection type used when it is not fully determined by the graph
        arguments.
    map_rel: callable
        The map relation used to apply `goal` to a sub-graph.
    """

    def walko_goal(s):

        nonlocal goal, rator_goal, graph_in, graph_out, null_type, map_rel

        graph_in_rf, graph_out_rf = reify((graph_in, graph_out), s)

        # No ground shape to follow.  Descending builds fresh rands and walks
        # them again, which recurses until ``cons`` overflows the stack.
        if isvar(graph_in_rf) and isvar(graph_out_rf):
            yield from goal(graph_in_rf, graph_out_rf)(s)
            return

        rator_in, rands_in, rator_out, rands_out = var(), var(), var(), var()

        _walko = partial(
            walko, goal, rator_goal=rator_goal, null_type=null_type, map_rel=map_rel
        )

        if rator_goal is None:
            descend_g = map_rel(_walko, graph_in_rf, graph_out_rf, null_type=null_type)
        else:
            descend_g = lall(
                applyo(rator_in, rands_in, graph_in_rf),
                applyo(rator_out, rands_out, graph_out_rf),
                rator_goal(rator_in, rator_out),
                map_rel(_walko, rands_in, rands_out, null_type=null_type),
            )

        g = conde(
            [Zzz(goal, graph_in_rf, graph_out_rf)],
            [descend_g],
        )

        yield from g(s)

    return walko_goal


_MISSING = object()


def term_walko(
    rator_goal,
    rands_goal,
    a,
    b=_MISSING,
    null_type=etuple,
    no_ident=False,
    format_step=None,
    **kwargs
):
    """Construct a goal for walking a term graph.

    ``term_walko(relation, in_term, out_term)`` applies ``relation`` at one
    position of a ground term (the root or one subterm).  ``reduceo`` repeats
    that.  When the input is unknown and the output is ground, the same call
    yields shortest preimages of ``relation``.

    ``term_walko(rator_goal, rands_goal, a, b)`` walks operator terms for
    associative and commutative unification.

    XXX: Make sure `rator_goal` will succeed for unground logic variables;
    otherwise, this will diverge.
    XXX: `rands_goal` should not contain `eq`, i.e. `rands_goal(x, x)`
    should always fail!
    """

    if b is _MISSING or not callable(rands_goal):
        relation, in_term, out_term = rator_goal, rands_goal, a

        def walk_goal(state):
            in_rf, out_rf = reify((in_term, out_term), state)
            if isvar(in_rf) and not isvar(out_rf):
                yield from reduceo(relation, in_term, out_term)(state)
            else:
                yield from _one_rewrite(relation, in_term, out_term)(state)

        return walk_goal

    def single_step(s, t):
        u, v = var(), var()
        u_rator, u_rands = var(), var()
        v_rands = var()

        return lall(
            ground_order((s, t), (u, v)),
            applyo(u_rator, u_rands, u),
            applyo(u_rator, v_rands, v),
            rator_goal(u_rator),
            Zzz(rands_goal, u_rands, v_rands, u_rator, **kwargs),
            _nonempty(u_rands),
            _nonempty(v_rands),
            _neq(u, v),
        )

    def term_walko_step(s, t):
        nonlocal rator_goal, rands_goal, null_type
        u, v = var(), var()
        z, w = var(), var()

        def descend(state):
            goal = lall(
                Zzz(map_anyo, term_walko_step, w, z, null_type=null_type),
                conde([eq(z, v)], [single_step(z, v)]),
            )
            yield from goal(state)

        return lall(
            ground_order((s, t), (u, v)),
            format_step(u, w) if format_step is not None else eq(u, w),
            conde(
                [single_step(w, v)],
                [descend],
            ),
        )

    if no_ident:
        return term_walko_step(a, b)

    # Fair interleave: first regrouping, the original term, the next one.
    return conde([term_walko_step(a, b)], [eq(a, b)])

from functools import partial

from unification import var, isvar
from unification import reify, unify

from etuples import etuple

from .core import eq, conde, lall, succeed, Zzz, fail, ground_order
from .goals import conso, nullo
from .term import applyo


def _neq(u, v):
    """Succeed when ``u`` and ``v`` are observably different.

    Unbound values are allowed through so a later goal can still ground them.
    """

    def neq_goal(s):
        u_rf, v_rf = reify((u, v), s)
        if isvar(u_rf) or isvar(v_rf):
            yield s
            return
        if unify(u_rf, v_rf, {}) is False:
            yield s

    return neq_goal


def _contains_var(term):
    if isvar(term):
        return True
    if isinstance(term, (list, tuple)):
        return any(_contains_var(x) for x in term)
    return False


def _same(a, b):
    try:
        return a == b
    except Exception:
        return False


def _is_noop(image, original):
    if isvar(image) or isvar(original):
        return False
    return _same(image, original)


def _has(term, terms):
    """Membership that does not require the term to be hashable."""
    return any(_same(term, item) for item in terms)


def _nonempty(seq):
    """Fail only when ``seq`` is already a ground empty collection.

    A logic variable is left alone.  ``conso`` would build an open tail here,
    and an associative step then answers with one leaf too many.
    """

    def goal(state):
        rf = reify(seq, state)
        if isvar(rf):
            yield state
            return
        if isinstance(rf, (list, tuple)) and len(rf) == 0:
            return
        yield state

    return goal


def _fair_gen(left, right):
    """Alternate two goal streams the way a fair ``conde`` does."""

    left, right = iter(left), iter(right)
    while True:
        try:
            yield next(left)
        except StopIteration:
            yield from right
            return
        try:
            yield next(right)
        except StopIteration:
            yield from left
            return


def mapo(relation, a, b, null_type=list, null_res=True, first=True):
    """Apply a relation to corresponding elements in two sequences and succeed if the relation succeeds for all pairs."""

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    return conde(
        [nullo(a, b, default_ConsNull=null_type) if (not first or null_res) else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            Zzz(relation, a_car, b_car),
            Zzz(
                mapo,
                relation,
                a_cdr,
                b_cdr,
                null_type=null_type,
                null_res=null_res,
                first=False,
            ),
        ],
    )


def map_anyo(
    relation, a, b, null_type=list, null_res=False, first=True, any_succeed=False
):
    """Apply a relation to corresponding elements in two sequences and succeed if at least one pair succeeds.

    Parameters
    ----------
    null_type: optional
       An object that's a valid cdr for the collection type desired.  If
       `False` (i.e. the default value), the cdr will be inferred from the
       inputs, or defaults to an empty list.
    """

    def _empty():
        if isinstance(null_type, type):
            return null_type()
        return []

    def _singleton(value):
        if null_type is etuple:
            return etuple(value)
        if null_type is tuple:
            return (value,)
        return [value]

    def _forward(seq, out_var, s, any_succ, is_first):
        """Ground list to unknown (or equally ground) list.

        Every successful application counts, even when the value does not
        change.  ``map_anyo(eq, xs, xs)`` is one success per non-empty subset
        of positions.
        """

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(out_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            b_car, b_cdr = var(), var()
            for s1 in relation(car, b_car)(s):
                image = reify(b_car, s1)
                for s2 in _forward(cdr, b_cdr, s1, True, False):
                    tail = reify(b_cdr, s2)
                    if isinstance(tail, list):
                        # Keep ``s1`` so bindings inside ``car`` (a guided
                        # ``add(q, 1)``) survive.  ``out_var`` is unified after
                        # those bindings, not against the pristine state.
                        yield from eq(out_var, [image] + tail)(s1)

        def eq_branch():
            b_cdr = var()
            for s2 in _forward(cdr, b_cdr, s, any_succ, False):
                tail = reify(b_cdr, s2)
                if isinstance(tail, list):
                    yield from eq(out_var, [car] + tail)(s2)

        yield from _fair_gen(rel_branch(), eq_branch())

    def _reverse(seq, in_var, s, any_succ, is_first):
        """Known output list, unknown input list."""

        if len(seq) == 0:
            if any_succ or (is_first and null_res):
                yield from eq(in_var, _empty())(s)
            return

        car, cdr = seq[0], seq[1:]

        def rel_branch():
            a_car, a_cdr = var(), var()
            for s1 in relation(a_car, car)(s):
                image = reify(a_car, s1)
                for s2 in _reverse(cdr, a_cdr, s1, True, False):
                    tail = reify(a_cdr, s2)
                    if isinstance(tail, list):
                        yield from eq(in_var, [image] + tail)(s1)

        def eq_branch():
            a_cdr = var()
            for s2 in _reverse(cdr, a_cdr, s, any_succ, False):
                tail = reify(a_cdr, s2)
                if isinstance(tail, list):
                    yield from eq(in_var, [car] + tail)(s2)

        yield from _fair_gen(rel_branch(), eq_branch())

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()
    allow_null = any_succeed or (first and null_res)

    relational = conde(
        [nullo(a, b, default_ConsNull=null_type) if allow_null else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            conde(
                [
                    Zzz(relation, a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=True,
                    ),
                ],
                [
                    eq(a_car, b_car),
                    Zzz(
                        map_anyo,
                        relation,
                        a_cdr,
                        b_cdr,
                        null_type=null_type,
                        null_res=null_res,
                        first=False,
                        any_succeed=any_succeed,
                    ),
                ],
            ),
        ],
    )

    def map_anyo_goal(s):
        a_rf, b_rf = reify((a, b), s)

        if type(a_rf) is list and not _contains_var(a_rf):
            yield from _forward(a_rf, b, s, any_succeed, first)
            return

        if isvar(a_rf) and type(b_rf) is list and not _contains_var(b_rf):
            yield from _reverse(b_rf, a, s, any_succeed, first)
            return

        # Lists that still contain variables (``[add(q, 1)]``) and other
        # partially-ground collections stay in the relational solver so the
        # variable bindings are part of the answer.
        if isvar(a_rf) and isvar(b_rf):
            if allow_null:
                yield from nullo(a, b, default_ConsNull=null_type)(s)
            return

        yield from relational(s)

    return map_anyo_goal


def vararg_success(*args):
    return succeed


def eq_length(u, v, default_ConsNull=list):
    """Construct a goal stating that two sequences are the same length and type."""

    return mapo(vararg_success, u, v, null_type=default_ConsNull)


def _rebuild(src, rator, rands):
    if type(src) is tuple:
        return (rator,) + tuple(rands)
    return etuple(rator, *rands)


def _one_rewrite(relation, src, dst, _depth=0):
    """``dst`` is ``src`` with ``relation`` applied at exactly one position.

    The root counts, and so does any argument of a compound term.  A term no
    rule matches fails, so the fixed-point search can tell "no step" apart
    from "zero steps".
    """

    def goal(state):
        if _depth > 24:
            return
        src_rf = reify(src, state)
        if isvar(src_rf):
            return

        produced = 0
        for st in relation(src_rf, dst)(state):
            produced += 1
            if produced > 16:
                break
            out = reify(dst, st)
            if not _is_noop(out, src_rf):
                yield st

        if not isinstance(src_rf, tuple) or len(src_rf) < 2:
            return

        rator = src_rf[0]
        children = list(src_rf[1:])
        for i, child in enumerate(children):
            child_out = var()
            child_n = 0
            for st in _one_rewrite(relation, child, child_out, _depth + 1)(state):
                child_n += 1
                if child_n > 16:
                    break
                new_child = reify(child_out, st)
                if isvar(new_child) or _is_noop(new_child, child):
                    continue
                new_children = list(children)
                new_children[i] = new_child
                built = _rebuild(src_rf, rator, new_children)
                if _is_noop(built, src_rf):
                    continue
                yield from eq(dst, built)(st)

    return goal


def _preimages(relation, target, state, limit=8):
    """Distinct one-step preimages of a ground target, with their states."""

    src = var()
    found = []
    try:
        stream = relation(src, target)(state)
    except TypeError:
        return
    for st in stream:
        val = reify(src, st)
        if isvar(val) or _is_noop(val, target) or _has(val, found):
            continue
        found.append(val)
        yield val, st
        if len(found) >= limit:
            return


def _iter_reductions(relation, term, state, out_term, stack, depth):
    """States in which ``out_term`` is a rewrite of ``term``.

    The state returned by each successful step is kept, so variables inside
    ``term`` (for example the ``q`` in ``add(q, 1)``) stay bound.  Longer
    chains are yielded before the partial step that led to them.
    """

    if depth > 12:
        return
    mid = var()
    found = []
    pairs = []
    n = 0
    try:
        stream = relation(term, mid)(state)
    except TypeError:
        return
    for st in stream:
        n += 1
        if n > 32:
            break
        val = reify(mid, st)
        if isvar(val) or _is_noop(val, term) or _has(val, found) or _has(val, stack):
            continue
        found.append(val)
        pairs.append((st, val))

    for st, val in pairs:
        yield from _iter_reductions(
            relation, val, st, out_term, stack + (term,), depth + 1
        )
        yield from eq(out_term, val)(st)


def reduceo(relation, in_term, out_term, *args, **kwargs):
    """Iterate a one-step relation.

    Forward mode yields every term reachable in one or more real rewrites,
    longest chains first.  A normal form fails instead of answering with
    itself.  Bindings created by a rewrite are part of the answer.

    Reverse mode (output ground, input unknown) yields a depth-first chain of
    preimages.  The unchanged term is not an answer.
    """

    kwargs.pop("_seen", None)
    kwargs.pop("_expanding", None)
    kwargs.pop("_no_ident", None)

    def reduceo_goal(s):
        in_rf, out_rf = reify((in_term, out_term), s)

        if isvar(in_rf) and not isvar(out_rf):
            # Depth-first so ``add(1, 1)`` is expanded to
            # ``log(exp(add(1, 1)))`` before the sibling ``log(exp(mul(2, 1)))``.
            seen = [out_rf]

            def expand(target, depth):
                if depth <= 0:
                    return
                for pre, _st in _preimages(relation, target, s):
                    if _has(pre, seen):
                        continue
                    seen.append(pre)
                    yield pre
                    yield from expand(pre, depth - 1)

            for pre in expand(out_rf, 32):
                yield from eq(in_term, pre)(s)
            return

        if isvar(in_rf):
            return

        yield from _iter_reductions(relation, in_rf, s, out_term, (), 0)

    return reduceo_goal


def walko(
    goal,
    graph_in,
    graph_out,
    rator_goal=None,
    null_type=etuple,
    map_rel=partial(map_anyo, null_res=True),
):
    """Apply a binary relation between all nodes in two graphs.

    When `rator_goal` is used, the graphs are treated as term graphs, and the
    multi-functions `rator`, `rands`, and `apply` are used to walk the graphs.
    Otherwise, the graphs must be iterable according to `map_anyo`.

    Parameters
    ----------
    goal: callable
        A goal that is applied to all terms in the graph.
    graph_in: object
        The graph for which the left-hand side of a binary relation holds.
    graph_out: object
        The graph for which the right-hand side of a binary relation holds.
    rator_goal: callable (default None)
        A goal that is applied to the rators of a graph.  When specified,
        `goal` is only applied to rands and it must succeed along with the
        rator goal in order to descend into sub-terms.
    null_type: type
        The collection type used when it is not fully determined by the graph
        arguments.
    map_rel: callable
        The map relation used to apply `goal` to a sub-graph.
    """

    def walko_goal(s):

        nonlocal goal, rator_goal, graph_in, graph_out, null_type, map_rel

        graph_in_rf, graph_out_rf = reify((graph_in, graph_out), s)

        # No ground shape to follow.  Descending builds fresh rands and walks
        # them again, which recurses until ``cons`` overflows the stack.
        if isvar(graph_in_rf) and isvar(graph_out_rf):
            yield from goal(graph_in_rf, graph_out_rf)(s)
            return

        rator_in, rands_in, rator_out, rands_out = var(), var(), var(), var()

        _walko = partial(
            walko, goal, rator_goal=rator_goal, null_type=null_type, map_rel=map_rel
        )

        if rator_goal is None:
            descend_g = map_rel(_walko, graph_in_rf, graph_out_rf, null_type=null_type)
        else:
            descend_g = lall(
                applyo(rator_in, rands_in, graph_in_rf),
                applyo(rator_out, rands_out, graph_out_rf),
                rator_goal(rator_in, rator_out),
                map_rel(_walko, rands_in, rands_out, null_type=null_type),
            )

        g = conde(
            [Zzz(goal, graph_in_rf, graph_out_rf)],
            [descend_g],
        )

        yield from g(s)

    return walko_goal


_MISSING = object()


def term_walko(
    rator_goal,
    rands_goal,
    a,
    b=_MISSING,
    null_type=etuple,
    no_ident=False,
    format_step=None,
    **kwargs
